ebytes=open(ejp,'rb').read(); text=ebytes.decode('utf-8','replace'); obj=json.loads(text)
# Print only structural clues; never emit usernames, passwords, or their hashes.
summary={'entries_json_type':type(obj).__name__,'entries_json_top_keys':list(obj.keys()) if isinstance(obj,dict) else None,'entries_json_count':len(obj) if isinstance(obj,list) else None}
# Search recursive entries and report only field names, lengths, and offsets for password-like literals.
def walk(x,path=[]):
 if isinstance(x,dict):
  keys=set(x.keys())
  if any(k.lower() in ('password','username','user_name','title') for k in keys):
   vals={k:v for k,v in x.items() if k.lower() in ('password','username','user_name','title') and isinstance(v,str)}
   if vals:
    details={'path':path,'fields':{k:{'chars':len(v),'utf8_bytes':len(v.encode())} for k,v in vals.items()}}
    # Record offsets of values only; do not output values.
    loc={}
    for k,v in vals.items():
     enc=json.dumps(v,ensure_ascii=False)[1:-1].encode('utf-8')
     offs=[]; start=0
     while enc and (p:=ebytes.find(enc,start))>=0: offs.append(p); start=p+1
     loc[k]=offs[:5]
    details['value_offsets_in_entries_json']=loc
    summary.setdefault('entries_with_credential_fields',[]).append(details)
  for k,v in x.items(): walk(v,path+[str(k)])
 elif isinstance(x,list):
  for i,v in enumerate(x): walk(v,path+[str(i)])
walk(obj)
# Parse KeePass XML. Namespace agnostic.
def child(el,name): return next((c for c in el if c.tag.split('}')[-1]==name),None)
def val(el,name):
 c=child(el,name); return (c.text or '') if c is not None else None
rt=ET.fromstring(open(xp,'rb').read())
meta=next((e for e in rt.iter() if e.tag.split('}')[-1]=='Meta'),None)
rb_enabled=val(meta,'RecycleBinEnabled') if meta is not None else None
rb_uuid=val(meta,'RecycleBinUUID') if meta is not None else None
summary['xml_recyclebin_enabled']=rb_enabled
summary['xml_recyclebin_uuid_present']=bool(rb_uuid)
summary['xml_recyclebin_uuid_offset']=open(xp,'rb').read().find(rb_uuid.encode()) if rb_uuid else None
root=next((e for e in rt.iter() if e.tag.split('}')[-1]=='Root'),None)
paths=[]; groups=[]
def group_walk(g,path):
 name=val(g,'Name') or ''; gp=path+[name]
 uuid=val(g,'UUID'); entries=[c for c in g if c.tag.split('}')[-1]=='Entry']
 groups.append({'path':gp,'uuid_matches_recyclebin':bool(uuid and rb_uuid and uuid==rb_uuid),'entry_count':len(entries),'uuid_offset_xml':open(xp,'rb').read().find(uuid.encode()) if uuid else None})
 for i,e in enumerate(entries):
  if rb_uuid and uuid==rb_uuid:
   fieldmap={}
   for s in (c for c in e if c.tag.split('}')[-1]=='String'):
    k=val(s,'Key'); v=child(s,'Value')
    if k and v is not None:
     vv=v.text or ''
     fieldmap[k]={'chars':len(vv),'utf8_bytes':len(vv.encode()),'offset_xml':open(xp,'rb').read().find(vv.encode()) if vv else None}
   times=child(e,'Times'); deltime=val(times,'DeletionTime') if times is not None else None
   summary.setdefault('xml_recyclebin_entries',[]).append({'path':gp,'entry_index':i,'fields':fieldmap,'deletion_time_present':bool(deltime),'deletion_time_offset':open(xp,'rb').read().find(deltime.encode()) if deltime else None})
 for c in (c for c in g if c.tag.split('}')[-1]=='Group'): group_walk(c,gp)
if root:
 for g in (c for c in root if c.tag.split('}')[-1]=='Group'): group_walk(g,[])
summary['xml_groups']=groups
print(json.dumps(summary,indent=2))
open(os.path.join(os.environ['OUT'],'keepass-structure-redacted.json'),'w').write(json.dumps(summary,indent=2))
